    25  void TMS320C64x_post_printer(csh ud, cs_insn *insn, char *insn_asm, MCInst *mci)
    26  {
    27          SStream ss;
    28          char *p, *p2, tmp[8];
    29          unsigned int unit = 0;
    30          int i;
    31          cs_tms320c64x *tms320c64x;
    32
    33          if (mci->csh->detail) {
    34                  tms320c64x = &mci->flat_insn->detail->tms320c64x;
    35
    36                  for (i = 0; i < insn->detail->groups_count; i++) {
    37                          switch(insn->detail->groups[i]) {
    38                                  case TMS320C64X_GRP_FUNIT_D:
    39                                          unit = TMS320C64X_FUNIT_D;
    40                                          break;
    41                                  case TMS320C64X_GRP_FUNIT_L:
    42                                          unit = TMS320C64X_FUNIT_L;
    43                                          break;
    44                                  case TMS320C64X_GRP_FUNIT_M:
    45                                          unit = TMS320C64X_FUNIT_M;
    46                                          break;
    47                                  case TMS320C64X_GRP_FUNIT_S:
    48                                          unit = TMS320C64X_FUNIT_S;
    49                                          break;
    50                                  case TMS320C64X_GRP_FUNIT_NO:
    51                                          unit = TMS320C64X_FUNIT_NO;
    52                                          break;
    53                          }
    54                          if (unit != 0)
    55                                  break;
    56                  }
    57                  tms320c64x->funit.unit = unit;
    58
    59                  SStream_Init(&ss);
    60                  if (tms320c64x->condition.reg != TMS320C64X_REG_INVALID)
    61                          SStream_concat(&ss, "[%c%s]|", (tms320c64x->condition.zero == 1) ? '!' : '|', cs_reg_name(ud, tms320c64x->condition.reg));
    62                  else
    63                          SStream_concat0(&ss, "||||||");
    64
    65                  p = strchr(insn_asm, '\t');
    66                  if (p != NULL)
    67                          *p++ = '\0';
    68
    69                  SStream_concat0(&ss, insn_asm);
    70                  if ((p != NULL) && (((p2 = strchr(p, '[')) != NULL) || ((p2 = strchr(p, '(')) != NULL))) {
    71                          while ((p2 > p) && ((*p2 != 'a') && (*p2 != 'b')))
    72                                  p2--;
    73                          if (p2 == p) {
    74                                  strcpy(insn_asm, "Invalid!");
    75                                  return;
    76                          }
    77                          if (*p2 == 'a')
    78                                  strcpy(tmp, "1T");
    79                          else
    80                                  strcpy(tmp, "2T");
    81                  } else {
    82                          tmp[0] = '\0';
    83                  }
    84                  switch(tms320c64x->funit.unit) {
    85                          case TMS320C64X_FUNIT_D:
    86                                  SStream_concat(&ss, ".D%s%u", tmp, tms320c64x->funit.side);
    87                                  break;
    88                          case TMS320C64X_FUNIT_L:
    89                                  SStream_concat(&ss, ".L%s%u", tmp, tms320c64x->funit.side);
